<?php $pageTitle='Edit User';require '../includes/admin-header.php';$pdo=db();$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM users WHERE id=?');$q->execute([$id]);$u=$q->fetch();if(!$u)go('admin/users.php');if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('UPDATE users SET full_name=?,username=?,email=?,mobile=?,address=?,status=? WHERE id=?')->execute([trim($_POST['full_name']),trim($_POST['username']),trim($_POST['email']),trim($_POST['mobile']),trim($_POST['address']),$_POST['status'],$id]);flash('success','User updated.');go('admin/users.php');} ?><form method="post" class="card card-body" style="max-width:700px"><div class="row g-3"><div class="col-md-6"><input class="form-control" name="full_name" value="<?=e($u['full_name'])?>"></div><div class="col-md-6"><input class="form-control" name="username" value="<?=e($u['username'])?>"></div><div class="col-md-6"><input class="form-control" name="email" value="<?=e($u['email'])?>"></div><div class="col-md-6"><input class="form-control" name="mobile" value="<?=e($u['mobile'])?>"></div><div class="col-md-6"><select class="form-select" name="status"><option value="blocked" <?=$u['status']==='blocked'?'selected':''?>>Blocked</option><option value="active" <?=$u['status']==='active'?'selected':''?>>Active</option></select></div><div class="col-12"><textarea class="form-control" name="address"><?=e($u['address'])?></textarea></div><div><button class="btn btn-dark">Save changes</button></div></div></form><?php require '../includes/admin-footer.php'; ?>
